<?php require 'config/database.php';require 'config/app.php';$rows=$pdo->query("SELECT s.*,t.name AS tournament_name FROM scores s JOIN tournaments t ON t.tournament_id=s.tournament_id ORDER BY s.total_points DESC,s.placement ASC LIMIT 50")->fetchAll();$pageTitle='Leaderboard';require 'includes/header.php';?><section class="page-hero"><div class="eyebrow">EVERY POINT COUNTS</div><h1>CLIMB THE <span>RANKS.</span></h1><p>Official standings published by tournament administrators.</p></section><section class="box section"><div class="section-head"><div><div class="eyebrow">OFFICIAL STANDINGS</div><h2>THE <span>TOP FRAGGERS.</span></h2></div></div><?php if($rows):?><div class="table-responsive"><table class="table arena-table"><thead><tr><th>RANK</th><th>TEAM</th><th>TOURNAMENT</th><th>PLACEMENT</th><th>ELIMINATIONS</th><th>TOTAL</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></td><td><b><?=e($r['team_name'])?></b></td><td><?=e($r['tournament_name'])?></td><td>#<?=(int)$r['placement']?></td><td><?=(int)$r['elimination_points']?></td><td><b class="hot-text"><?=(int)$r['total_points']?></b></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty"><h3>The board is waiting for its first result.</h3><p>Standings appear after an admin publishes scores.</p></div><?php endif;?></section><?php require 'includes/footer.php';?>
